/* Workspace redesign direction */
:root{
  --mrs-bg:#f8fafc;
  --mrs-surface:#ffffff;
  --mrs-surface-2:#f1f5f9;
  --mrs-surface-3:#e2e8f0;
  --mrs-border:rgba(148,163,184,.25);
  --mrs-border-strong:rgba(148,163,184,.35);
  --mrs-text:#0f172a;
  --mrs-muted:#64748b;
  --mrs-muted-2:#94a3b8;
  --mrs-primary:#2563eb;
  --mrs-primary-hover:#3b82f6;
  --mrs-primary-soft:rgba(37,99,235,.12);
  --mrs-green:#10b981;
  --mrs-yellow:#f59e0b;
  --mrs-red:#ef4444;
  --mrs-blue-file:#2563eb;
  --mrs-radius-sm:8px;
  --mrs-radius-md:12px;
  --mrs-radius-lg:16px;
  --mrs-shadow-panel:0 12px 32px rgba(15,23,42,.08);
}
[data-theme="dark"]{
  --mrs-bg:#0f172a;
  --mrs-surface:#1e293b;
  --mrs-surface-2:#334155;
  --mrs-surface-3:#475569;
  --mrs-border:rgba(148,163,184,.30);
  --mrs-border-strong:rgba(148,163,184,.40);
  --mrs-text:#f1f5f9;
  --mrs-muted:#94a3b8;
  --mrs-muted-2:#cbd5e1;
  --mrs-primary:#3b82f6;
  --mrs-primary-hover:#60a5fa;
  --mrs-primary-soft:rgba(59,130,246,.15);
  --mrs-green:#34d399;
  --mrs-yellow:#fbbf24;
  --mrs-red:#f87171;
  --mrs-blue-file:#3b82f6;
  --mrs-radius-sm:8px;
  --mrs-radius-md:12px;
  --mrs-radius-lg:16px;
  --mrs-shadow-panel:0 16px 40px rgba(0,0,0,.35);
}
.workspaceTopbar{
  min-height:56px;
  max-height:64px;
  height:auto;
  padding:12px 16px;
  gap:10px;
  background:linear-gradient(180deg,rgba(7,17,31,.98),rgba(5,11,22,.96));
  border-bottom:1px solid var(--mrs-border);
  overflow:visible;
}
.workspaceLogo,.workspaceTitle{
  display:none;
}
.workspaceSearchBox{
  position:relative;
  flex:0 1 280px;
  width:clamp(220px,24vw,280px);
}
.searchIcon{
  position:absolute;
  left:11px;
  top:50%;
  width:13px;
  height:13px;
  transform:translateY(-50%);
  border:2px solid var(--mrs-muted);
  border-radius:999px;
  pointer-events:none;
}
.searchIcon:after{
  content:"";
  position:absolute;
  width:6px;
  height:2px;
  right:-5px;
  bottom:-3px;
  border-radius:999px;
  background:var(--mrs-muted);
  transform:rotate(45deg);
}
.workspaceSearch{
  width:100%;
  margin:0;
  height:36px;
  padding-left:33px;
  border-color:var(--mrs-border-strong);
  background:var(--mrs-surface-2);
}
.workspaceCompany{
  width:100%;
  min-width:0!important;
  height:36px;
  background:var(--mrs-surface-2);
}
.workspaceTopbar .btn{
  min-height:36px;
  border-radius:var(--mrs-radius-md);
  border-color:var(--mrs-border);
  background:var(--mrs-surface-2);
  box-shadow:none;
}
.workspaceTopbar .btn.primary{
  background:var(--mrs-primary);
  border-color:rgba(91,130,255,.72);
  color:#fff;
}
.workspaceTopbar .btn.primary:hover{
  background:var(--mrs-primary-hover);
}
.workspaceTopbar .btn.secondary{
  color:var(--mrs-text);
  background:var(--mrs-surface-2);
}
.workspaceMobileMore{
  display:none;
}
.topbarAdvanced,.workspaceMenu,.workspaceMobileMore{
  position:relative;
  flex:0 0 auto;
}
.topbarAdvanced summary,.workspaceMenu summary,.workspaceMobileMore summary{
  list-style:none;
}
.topbarAdvanced summary::-webkit-details-marker,.workspaceMenu summary::-webkit-details-marker,.workspaceMobileMore summary::-webkit-details-marker{
  display:none;
}
.advancedMenu,.workspaceMenuPanel{
  position:absolute;
  right:0;
  top:calc(100% + 8px);
  z-index:60;
  display:grid;
  gap:6px;
  min-width:190px;
  padding:8px;
  border:1px solid var(--mrs-border-strong);
  border-radius:var(--mrs-radius-md);
  background:var(--mrs-surface);
  box-shadow:var(--mrs-shadow-panel);
}
.advancedMenu .btn,.workspaceMenuPanel .btn{
  justify-content:flex-start;
  width:100%;
}
.workspaceUserPill{
  width:36px;
  height:36px;
  justify-content:center;
  padding:0;
  border-radius:999px;
  background:var(--mrs-primary-soft);
  border-color:rgba(91,130,255,.42);
  color:var(--mrs-text);
  font-size:12px;
}
.workspaceLayout{
  height:calc(100vh - 64px);
  display:grid;
  grid-template-columns:minmax(260px,1fr) 12px minmax(260px,var(--workspace-side,360px));
  grid-template-rows:minmax(220px,var(--workspace-top,46%)) 12px minmax(260px,1fr);
  gap:0;
  padding:12px;
}
.workspaceLayout .splitX,.workspaceLayout .splitY{
  display:grid;
  place-items:center;
  border-radius:999px;
  touch-action:none;
  user-select:none;
  opacity:.72;
  transition:opacity .16s ease,background .16s ease;
}
.workspaceLayout .splitX{
  grid-column:2;
  grid-row:1/4;
  cursor:col-resize;
}
.workspaceLayout .splitY{
  grid-column:1;
  grid-row:2;
  cursor:row-resize;
}
.workspaceLayout .splitX:hover,.workspaceLayout .splitY:hover,
.workspaceResizing .workspaceLayout .splitX,.workspaceResizing .workspaceLayout .splitY{
  opacity:1;
  background:rgba(91,130,255,.10);
}
.workspaceLayout .splitDot{
  background:var(--mrs-border-strong);
  box-shadow:none;
}
.workspaceLayout .splitX:hover .splitDot,.workspaceLayout .splitY:hover .splitDot,
.workspaceResizing .workspaceLayout .splitDot{
  background:var(--mrs-primary);
}
.workspaceLayout [data-workspace-slot="side"]{
  grid-column:3;
  grid-row:1/4;
}
.workspaceLayout [data-workspace-slot="bottom"]{
  grid-column:1;
  grid-row:3;
}
.workspaceLayout [data-workspace-slot="top"]{
  grid-column:1;
  grid-row:1;
}
.workspaceLayout .panelHead[data-workspace-handle]{
  cursor:grab;
}
.workspaceLayout .panelHead[data-workspace-handle]:active{
  cursor:grabbing;
}
.workspaceLayout .workspacePanelDragging{
  opacity:.58;
}
.workspaceLayout .workspacePanelDropTarget{
  border-color:rgba(91,130,255,.72);
  box-shadow:0 0 0 1px rgba(91,130,255,.48),var(--mrs-shadow-panel);
}
.workspaceLayout .panel{
  border-radius:var(--mrs-radius-lg);
  border-color:var(--mrs-border);
  background:linear-gradient(180deg,var(--mrs-surface),var(--mrs-surface-2));
  box-shadow:var(--mrs-shadow-panel);
}
.materialsHeader{
